using System;
using Aspose.BarCode.Generation;
using Aspose.BarCode;

namespace Ean13Demo
{
    class Program
    {
        static void Main(string[] args)
        {
            // Initialize the barcode generator for EAN-13
            var generator = new BarcodeGenerator(EncodeTypes.EAN13);

            // Set the 12‑digit data; checksum will be added automatically
            generator.CodeText = "590123412345";

            // Ensure checksum calculation is enabled
            generator.Parameters.Barcode.ChecksumMode = ChecksumMode.Auto;

            // Optional: customize image appearance
            generator.Parameters.Image.Width = 300;
            generator.Parameters.Image.Height = 150;
            generator.Parameters.Image.ForeColor = System.Drawing.Color.Black;
            generator.Parameters.Image.BackColor = System.Drawing.Color.White;

            // Save the barcode as a PNG file
            generator.Save("ean13.png", BarCodeImageFormat.Png);

            Console.WriteLine("EAN-13 barcode generated successfully.");
        }
    }
}

using System;
using Aspose.BarCode.Generation;

namespace HighDensityDataMatrixDemo
{
    class Program
    {
        static void Main(string[] args)
        {
            // Initialise the generator for DataMatrix symbology
            var generator = new BarCodeGenerator(EncodeTypes.DataMatrix);

            // Set the data to encode
            generator.CodeText = "1234567890ABCDEFGHIJ";

            // High‑density configuration
            generator.Parameters.Barcode.DataMatrixEncodeMode = DataMatrixEncodeMode.Auto;
            generator.Parameters.Barcode.DataMatrixSize = DataMatrixSize.Size10x10; // smallest possible
            generator.Parameters.ImageResolution = 300; // DPI for crisp output
            generator.Parameters.Barcode.QRQuietZone = 0; // minimal quiet zone
            generator.Parameters.ImageFormat = BarCodeImageFormat.Png;

            // Save the barcode image
            generator.Save("HighDensityDataMatrix.png");

            Console.WriteLine("High density Data Matrix barcode generated successfully.");
        }
    }
}

using System;
using Aspose.BarCode.Generation;

namespace UpcBarcodeDemo
{
    class Program
    {
        static void Main()
        {
            // UPC‑A example (12 digits, includes checksum)
            var upcAGenerator = new BarcodeGenerator(EncodeTypes.UpcA, "012345678905");
            upcAGenerator.Parameters.ImageFormat = ImageFormat.Png;
            upcAGenerator.Parameters.ImageResolution = 300;
            upcAGenerator.Save("upc_a.png");

            // UPC‑E example (8 digits, includes checksum)
            var upcEGenerator = new BarcodeGenerator(EncodeTypes.UpcE, "01234565");
            upcEGenerator.Parameters.ImageFormat = ImageFormat.Png;
            upcEGenerator.Parameters.ImageResolution = 300;
            upcEGenerator.Save("upc_e.png");

            Console.WriteLine("UPC barcodes generated successfully.");
        }
    }
}

